-- ============================================================
-- EX 603 reference dataset: Multiplayer Game Telemetry / Live Ops
-- Generated deterministically (seed 603). Do not edit by hand.
-- Load with:  createdb ex603_gaming && psql -d ex603_gaming -f gaming.sql
-- ============================================================
-- PostgreSQL load:  createdb ex603_gaming  &&  psql -d ex603_gaming -f gaming.sql
-- (Re-running is safe: every table is dropped first, children before parents.)
DROP TABLE IF EXISTS match_participants CASCADE;
DROP TABLE IF EXISTS match_modes CASCADE;
DROP TABLE IF EXISTS match_platforms CASCADE;
DROP TABLE IF EXISTS game_modes CASCADE;
DROP TABLE IF EXISTS matches CASCADE;
DROP TABLE IF EXISTS players CASCADE;

-- ---------- actor ----------
CREATE TABLE players (
    player_id        INT           NOT NULL,
    player_name      VARCHAR(120)  NOT NULL,
    signup_date      DATE          NOT NULL,
    region    VARCHAR(80)   NOT NULL,
    gamertag    VARCHAR(160)  NOT NULL,
    recruited_by INT           NULL,
    is_active      BOOLEAN       NOT NULL DEFAULT TRUE,
    PRIMARY KEY (player_id),
    CONSTRAINT uq_players_gamertag UNIQUE (gamertag),
    CONSTRAINT ck_players_no_self CHECK (recruited_by IS NULL OR recruited_by <> player_id),
    CONSTRAINT fk_players_ref FOREIGN KEY (recruited_by)
        REFERENCES players (player_id) ON DELETE SET NULL
);

-- ---------- producer ----------
CREATE TABLE matches (
    match_id        INT           NOT NULL,
    match_label      VARCHAR(120)  NOT NULL,
    scheduled_on      DATE          NOT NULL,
    server_region    VARCHAR(80)   NOT NULL,
    match_code    VARCHAR(60)   NOT NULL,
    player_count    SMALLINT NOT NULL,
    is_ranked      BOOLEAN       NOT NULL DEFAULT TRUE,
    PRIMARY KEY (match_id),
    CONSTRAINT uq_matches_match_code UNIQUE (match_code),
    CONSTRAINT ck_matches_metric CHECK (player_count > 0 AND player_count <= 64)
);

-- ---------- multivalued attribute, resolved ----------
CREATE TABLE match_platforms (
    match_id   INT       NOT NULL,
    platform_code  CHAR(2) NOT NULL,
    PRIMARY KEY (match_id, platform_code),
    CONSTRAINT fk_match_platforms_owner FOREIGN KEY (match_id)
        REFERENCES matches (match_id) ON DELETE CASCADE
);

-- ---------- catalog ----------
CREATE TABLE game_modes (
    mode_id    INT          NOT NULL,
    mode_name  VARCHAR(60)  NOT NULL,
    mode_description  VARCHAR(200) NULL,
    PRIMARY KEY (mode_id),
    CONSTRAINT uq_game_modes_name UNIQUE (mode_name)
);

-- ---------- junction: producer to catalog, composite PK ----------
CREATE TABLE match_modes (
    match_id   INT  NOT NULL,
    mode_id   INT  NOT NULL,
    enabled_on DATE NOT NULL,
    PRIMARY KEY (match_id, mode_id),
    CONSTRAINT fk_match_modes_prod FOREIGN KEY (match_id)
        REFERENCES matches (match_id) ON DELETE CASCADE,
    CONSTRAINT fk_match_modes_cat FOREIGN KEY (mode_id)
        REFERENCES game_modes (mode_id) ON DELETE RESTRICT
);

-- ---------- event: the high volume fact table ----------
CREATE TABLE match_participants (
    participation_id       BIGINT        NOT NULL,
    player_id       INT           NOT NULL,
    match_id       INT           NOT NULL,
    joined_at       TIMESTAMP      NOT NULL,
    left_at      TIMESTAMP      NULL,
    client_region   VARCHAR(80)   NOT NULL,
    score   DECIMAL(8,2) NOT NULL,
    duration_min   DECIMAL(7,2) NOT NULL,
    xp_multiplier    DECIMAL(4,2)  NOT NULL DEFAULT 1.00,
    participation_status   VARCHAR(20)   NOT NULL,
    disconnect_reason   VARCHAR(60)   NULL,     -- nullable by design
    PRIMARY KEY (participation_id),
    CONSTRAINT ck_match_participants_metric_pos  CHECK (score >= 0),
    CONSTRAINT ck_match_participants_second_pos  CHECK (duration_min > 0),
    CONSTRAINT ck_match_participants_third_min   CHECK (xp_multiplier >= 1.00),
    CONSTRAINT ck_match_participants_time_order  CHECK (left_at IS NULL OR left_at >= joined_at),
    CONSTRAINT fk_match_participants_actor FOREIGN KEY (player_id)
        REFERENCES players (player_id) ON DELETE RESTRICT,
    CONSTRAINT fk_match_participants_prod FOREIGN KEY (match_id)
        REFERENCES matches (match_id) ON DELETE RESTRICT
);

